enum AcpStartupTarget {
    Ask {
        gameengine_session_id: String,
        prompt: String,
    },
    Build {
        gameengine_session_id: String,
        run_id: String,
        prompt: String,
        workspace: CodeWorkspace,
    },
}

impl AcpStartupTarget {
    fn is_ask(&self) -> bool {
        matches!(self, Self::Ask { .. })
    }
}

